from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import EHRRecord
from .serializers import EHRRecordSerializer

class ClinicalRecordSearchView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        jsonb_criteria = request.data.get('clinical_filter')
        if not isinstance(jsonb_criteria, dict):
            return Response({'error': 'clinical_filter must be an object'}, status=status.HTTP_400_BAD_REQUEST)

        records = EHRRecord.objects.filter(
            facility=request.user.assigned_facility,
            clinical_data__contains=jsonb_criteria
        )[:50]
        serializer = EHRRecordSerializer(records, many=True)
        return Response(serializer.data)
